export interface ThreatIndicator {
  element: string;
  value: string;
  assessment:
    | 'MALICIOUS'
    | 'FRAUDULENT'
    | 'FABRICATED'
    | 'SUSPICIOUS'
    | 'HIGH RISK'
    | 'STALKING / BLIND'
    | 'INFORMATIONAL';
  findings: string[];
}

export interface SafetyTip {
  headline: string;
  tip: string;
}

// A single { label, value } fact used to populate the report's scan-metadata
// summary table (e.g. Domain, Sender, SSL Status). Generated by the model
// itself, tailored to whatever was actually found in the input.
export interface MetaRow {
  label: string;
  value: string;
}

export interface ScamResult {
  scanId: string;
  riskScore: number; // 0-100
  riskLevel: 'high' | 'medium' | 'low';
  explanation: string;
  // AI now returns structured { headline, tip } objects so the recommendation
  // headline is generated by the model itself rather than guessed from keywords.
  safetyTips: SafetyTip[];
  // ── AI-generated dossier fields (optional for backward compatibility) ──
  threatType?: string;
  cvss?: string; // e.g. "8.5/10"
  status?: string; // e.g. "Active Phishing Campaign"
  indicators?: ThreatIndicator[];
  // ── AI-generated report presentation fields ──
  // A specific, tailored title for this exact case (e.g. "PayPal
  // Credential-Harvesting Phishing Report") rather than a generic static one.
  reportTitle?: string;
  // The specific brand/company/entity being impersonated or targeted, or
  // "None Identified" if no brand impersonation is present.
  targetBrand?: string;
  // 2-4 concrete facts about this scan (Domain, Sender, SSL Status, etc.)
  // for the report's summary table, tailored per scan type by the model.
  metaRows?: MetaRow[];
}

export interface FaqItem {
  question: string;
  answer: string;
}

export interface FeatureItem {
  title: string;
  text: string;
  icon: React.ElementType;
  color: string;
}

export interface TechniqueItem {
  title: string;
  description: string;
  icon: React.ElementType;
}

export interface FooterLink {
  label: string;
  href: string;
}

export interface FooterSection {
  title: string;
  links: FooterLink[];
}